# Diyet Problemi - PuLP
from pulp import *

fiyat = {'Ekmek': 0.5, 'Sut': 1.2, 'Peynir': 2.0}
protein = {'Ekmek': 3, 'Sut': 8, 'Peynir': 25}

prob = LpProblem('Diyet', LpMinimize)
x = {f: LpVariable(f, lowBound=0) for f in fiyat}

prob += lpSum(fiyat[f]*x[f] for f in fiyat)
prob += lpSum(protein[f]*x[f] for f in fiyat) >= 50  # min 50g protein

prob.solve()
for f in fiyat:
    print(f'{f}: {x[f].value()}')
